import { describe, expect, it } from "vitest";
import base from "../../public/data/abbreviations.base.json";
import rules from "../../public/data/abbreviation-rules.json";
import overrides from "../../public/data/abbreviation-overrides.json";
import { dataset } from "./testDataset";

/** Expected pairs transcribed from the authority, not generated by the engine. */
const omittedSourcePairs = [
  ["Cycle Ending Exercise", "CEE"],
  ["Drop Zone", "DZ"],
  ["Estimated Time of Departure", "ETD"],
  ["Furthest-on Circles", "FOC"],
  ["Hybrid Warfare", "HW"],
  ["Issue Voucher", "IV"],
  ["Junior Command and Staff Course", "JCSC"],
  ["Lubricate", "lub"],
  ["Muzzle Velocity", "MV"],
  ["Number", "no"],
  ["Over the Horizon", "OTH"],
  ["Put Up Separately", "PUS"],
  ["Quick Reaction/Response Force", "QRF"],
  ["Rules of Engagement Request", "ROEREQ"],
  ["System", "sys"],
  ["Training", "trg"],
  ["Tug Repair and Logistic Area", "TRALA"],
] as const;

function authoritativePair(fullForm: string, abbreviation: string, annex?: string) {
  return base.entries.find((entry) => entry.full_form === fullForm && entry.abbreviation === abbreviation
    && (annex === undefined || entry.annex === annex));
}

function runtimePair(fullForm: string, abbreviation: string) {
  return dataset.entries.find((entry) => entry.abbreviation === abbreviation
    && entry.match_variants.some((variant) => variant.toLowerCase() === fullForm.toLowerCase()));
}

describe("source dictionary reconciliation", () => {
  it.each(omittedSourcePairs)("retains the source table pair %s → %s", (full, abbreviation) => {
    const pair = authoritativePair(full, abbreviation, "A");
    expect(pair).toBeDefined();
    expect(pair?.verified).toBe(true);
    expect(pair).toHaveProperty("source_location.document", "ABBREVIATIONS AND SYMBOLS.docx");
  });

  it("keeps the two institutions in the merged training table separate", () => {
    expect(authoritativePair("Bangladesh Institute of Peace Support Operation and Training", "BIPSOT", "E")).toBeDefined();
    expect(authoritativePair("Bangladesh Infantry Regimental Centre", "BIRC", "E")).toBeDefined();
    expect(authoritativePair("Bangladesh Infantry Regimental Centre", "BIPSOT")).toBeUndefined();
    expect(authoritativePair("Binocular", "Bino", "A")).toBeDefined();
    expect(authoritativePair("Bir Bikram", "BB", "A")).toBeDefined();
    expect(base.entries.some((entry) => entry.full_form === "Binocular Bir Bikram")).toBe(false);
  });

  it("restores wrapped full forms and their entire abbreviation cells", () => {
    expect(authoritativePair("Additional Military Assistant (Operations and Training)", "AMA (O&T)", "C")).toBeDefined();
    expect(authoritativePair("Additional Military Assistant (Protocol and External Affairs)", "AMA (P&EA)", "C")).toBeDefined();
    expect(authoritativePair("Director of Works and Chief Engineer (Army)", "DW&CE (Army)", "C")).toBeDefined();
    expect(authoritativePair("Commander Flotilla West", "COMFLOT WEST", "C")).toBeDefined();
    expect(authoritativePair("Director (Directorate) of Armament and Weapons", "DA&W/ Dte A&W", "C")).toBeDefined();
    expect(authoritativePair("Director (Directorate) of Medical Services (Air)", "DMS(Air)/ Dte MS(Air)", "C")).toBeDefined();
    expect(authoritativePair("Director (Directorate) of Welfare and Ceremony", "DW&C/ Dte W&C", "C")).toBeDefined();
    expect(base.entries.some((entry) => ["Training)", "Affairs)", "Note:"].includes(entry.full_form))).toBe(false);
  });

  it("uses service headings for appointments and keeps ranks of each service", () => {
    for (const entry of base.entries) {
      const number = Number(entry.id.slice(5));
      if (number >= 1810 && number <= 1944) expect(entry).toHaveProperty("service", "army");
      if (number >= 1945 && number <= 2156) expect(entry).toHaveProperty("service", "navy");
    }
    expect(base.entries.find((entry) => entry.id === "abbr-1980")).toMatchObject({
      full_form: "Commodore Special Warfare Diving and Salvage Command", service: "navy",
    });
    expect(base.entries.some((entry) => entry.annex === "C" && entry.full_form === "Officer Cadet"
      && "service" in entry && entry.service === "air-force")).toBe(true);
    expect(authoritativePair("Flight Lieutenant", "Flt Lt", "C")).toBeDefined();
    expect(authoritativePair("19 East Bengal Regiment (Divisional Support)", "19 EB (Div Sp)", "F")).toBeDefined();
  });

  it.each([
    ["BNS SALAM", "SLM"], ["BNS NISHAN", "NSN"], ["BNS KAPATAKHAYA", "KPT"],
    ["BNS KUSIYARA", "KUS"], ["BNS DORDANDA", "DNDA"], ["BNFC BALABAN", "BLBN"],
    ["BNS DOLPHIN", "DLPN"], ["BNS SHAH MAKHDUM", "SMKD"], ["LANDING CRAFT TANK-100", "LCT-100"],
  ])("keeps one correctly aligned Navy vessel %s → %s", (full, abbreviation) => {
    const entries = base.entries.filter((entry) => entry.annex === "G" && entry.full_form === full);
    expect(entries).toHaveLength(1);
    expect(entries[0].abbreviation).toBe(abbreviation);
  });

  it("preserves source automatic numbering and the manual's national codes", () => {
    expect(authoritativePair("314 MPA Squadron", "314 MPA Sqn", "G")).toBeDefined();
    expect(authoritativePair("315 MPA Squadron", "315 MPA Sqn", "G")).toBeDefined();
    expect(authoritativePair("7 Frigate Squadron", "7FS", "G")).toBeDefined();
    expect(base.entries.filter((entry) => entry.annex === "D")).toHaveLength(86);
    expect(authoritativePair("Sierra Leone", "SL", "D")).toBeDefined();
    expect(authoritativePair("Sri Lanka", "SL", "D")).toBeDefined();
    expect(authoritativePair("Oman", "MU", "D")).toBeDefined();
  });

  it("identifies the actual authority and records its fingerprint", () => {
    expect(base.source.filename).toBe("ABBREVIATIONS AND SYMBOLS.docx");
    expect(base.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(base.source.reviewed_on).toBe("2026-10-09");
    expect(base.entries.every((entry) => "source_location" in entry)).toBe(true);
  });
});

describe("explicit source notation surfaces", () => {
  it.each([
    ["Air to Air Guided Missile", "AAGM"], ["Commander Task Force", "CTF"],
    ["Landing Craft Utility", "LCU"], ["Short Take-off and Landing", "STOL"],
    ["Vertical Take-off and Landing", "VTOL"], ["Unmanned Aerial Vehicle", "UAV"],
    ["Very Very Important Person", "VVIP"], ["Estimated Time of Return", "ETR"],
    ["Tactical Air Support of Maritime Operations", "TASMO"],
    ["Directorate of Armament and Weapons", "Dte A&W"],
    ["Directorate of Medical Services (Air)", "Dte MS(Air)"],
  ])("materializes paired notation as %s → %s for either direction", (full, abbreviation) => {
    const pair = runtimePair(full, abbreviation);
    expect(pair).toBeDefined();
    expect(pair?.conversion_enabled).toBe(true);
    expect(pair?.meanings).toContain(full);
  });

  it("expands suffixes and shared phrases without creating word fragments", () => {
    expect(runtimePair("Improving", "impv")).toBeDefined();
    expect(runtimePair("Friendly Aircraft Movement", "FAM")).toBeDefined();
    expect(runtimePair("Humanitarian Assistance and Disaster Response", "HADR")).toBeDefined();
    expect(runtimePair("Response", "HADR")).toBeUndefined();
    expect(runtimePair("Publication", "GSTP")).toBeUndefined();
    expect(runtimePair("Instructional Technique", "IT")).toBeDefined();
    expect(runtimePair("Infantry Support Raft", "ISR")).toBeDefined();
    expect(runtimePair("Raft", "ISR")).toBeUndefined();
    expect(runtimePair("Reference", "Ref")).toBeDefined();
    expect(runtimePair("References", "Refs")).toBeDefined();
  });

  it("targets normalization and grammatical rules explicitly", () => {
    for (const override of overrides.overrides) {
      if (override.rule !== "add_conversion") expect(override).toHaveProperty("entry_id");
      if ("match_variants" in override && Array.isArray(override.match_variants)) {
        for (const surface of override.match_variants) {
          expect(surface.match(/\(/g)?.length ?? 0).toBe(surface.match(/\)/g)?.length ?? 0);
          expect(surface).not.toMatch(/(?:Movementnet|Improveing|Divide \/Division)/);
        }
      }
    }
    const knownErrors = ["approachs", "attachs", "carrys", "carryed", "controled", "controling",
      "speaked", "withdrawed", "supplys", "supplyed", "answership", "logisticses"];
    for (const rule of rules.rules) {
      expect(rule).toHaveProperty("entry_id");
      for (const example of knownErrors) expect(rule.examples).not.toHaveProperty(example);
    }
    expect(rules.rules.find((rule) => rule.root === "command")?.part_of_speech).toBe("verb");
    expect(rules.rules.find((rule) => rule.root === "answer")?.part_of_speech).toBe("verb");
    expect(rules.rules.find((rule) => rule.root === "refer")?.abbreviation).toBe("Ref");
    expect(rules.rules.find((rule) => rule.root === "deployment")?.examples).toMatchObject({
      deployment: "depl", deployments: "depl",
    });
  });
});
